//! Fixed Windows Apps uninstall registration. Not used as an installation-root authority.
use crate::error::{Error,Result};use super::{identity::{self,wide},security};use std::path::Path;use windows_sys::Win32::{Foundation::*,System::Registry::*,Storage::FileSystem::{WRITE_DAC,WRITE_OWNER,DELETE},Security::*,Security::Authorization::*};
const KEY:&str=r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Kat Client";
const NAMES:&[&str]=&["KatInstallerSchema","DisplayName","DisplayVersion","Publisher","InstallLocation","UninstallString","NoModify","NoRepair","DisplayIcon","EstimatedSize"];
fn bad()->Error{Error::new("INSTALL_APPS_REGISTRATION","Cannot safely register this application in Windows Apps")}
struct Key(HKEY);impl Drop for Key{fn drop(&mut self){unsafe{RegCloseKey(self.0);}}}
#[derive(Clone)]pub struct Snapshot(pub Option<Vec<(String,u32,Vec<u8>)>>);
fn get(k:HKEY,name:&str)->Result<Option<(u32,Vec<u8>)>>{unsafe{let mut kind=0;let mut n=0;let r=RegQueryValueExW(k,wide(name).as_ptr(),std::ptr::null(),&mut kind,std::ptr::null_mut(),&mut n);if r==ERROR_FILE_NOT_FOUND{return Ok(None);}if r!=0||n>65536{return Err(bad());}let mut b=vec![0;n as usize];if RegQueryValueExW(k,wide(name).as_ptr(),std::ptr::null(),&mut kind,b.as_mut_ptr(),&mut n)!=0{return Err(bad());}b.truncate(n as usize);Ok(Some((kind,b)))}}
fn string(v:&(u32,Vec<u8>))->Result<String>{if v.0!=REG_SZ||v.1.len()%2!=0{return Err(bad());}let b:Vec<u16>=v.1.chunks_exact(2).map(|b|u16::from_le_bytes([b[0],b[1]])).collect();Ok(String::from_utf16_lossy(&b).trim_end_matches('\0').to_string())}
fn check(k:HKEY)->Result<()>{unsafe{
 let mut owner=std::ptr::null_mut();let mut acl=std::ptr::null_mut();let mut sd=std::ptr::null_mut();if GetSecurityInfo(k.cast(),SE_REGISTRY_KEY,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&mut owner,std::ptr::null_mut(),&mut acl,std::ptr::null_mut(),&mut sd)!=0||sd.is_null()||acl.is_null(){return Err(bad());}
 let sid=|p:PSID|->Result<String>{let mut s=std::ptr::null_mut();if ConvertSidToStringSidW(p,&mut s)==0{return Err(bad());}let v=identity::string(s);LocalFree(s.cast());Ok(v)};
 let result=(||{if !["S-1-5-18","S-1-5-32-544"].contains(&sid(owner)?.as_str()){return Err(bad());}for n in 0..(*acl).AceCount{let mut a=std::ptr::null_mut();if GetAce(acl,n as u32,&mut a)==0{return Err(bad());}let h=&*a.cast::<ACE_HEADER>();if h.AceType==0{let a=&*a.cast::<ACCESS_ALLOWED_ACE>();if a.Mask&(GENERIC_ALL|GENERIC_WRITE|WRITE_DAC|WRITE_OWNER|DELETE|KEY_SET_VALUE|KEY_CREATE_SUB_KEY)!=0&&!["S-1-5-18","S-1-5-32-544"].contains(&sid((&a.SidStart as *const u32).cast_mut().cast())?.as_str()){return Err(bad());}}else if h.AceType!=1&&h.AceType!=2{return Err(bad());}}Ok(())})();LocalFree(sd);result
}}
pub fn snapshot(root:&Path)->Result<Snapshot>{unsafe{let mut h=std::ptr::null_mut();let r=RegOpenKeyExW(HKEY_LOCAL_MACHINE,wide(KEY).as_ptr(),0,KEY_READ|KEY_WOW64_64KEY,&mut h);if r==ERROR_FILE_NOT_FOUND{return Ok(Snapshot(None));}if r!=0{return Err(bad());}let h=Key(h);check(h.0)?;
 if get(h.0,"KatInstallerSchema")?!=Some((REG_DWORD,1u32.to_le_bytes().to_vec())){return Err(bad());}
 let location=string(&get(h.0,"InstallLocation")?.ok_or_else(bad)?)?;if !security::same_path(Path::new(&location),root){return Err(bad());}
 let mut rows=vec![];for name in NAMES{if let Some((kind,b))=get(h.0,name)?{rows.push((name.to_string(),kind,b));}}Ok(Snapshot(Some(rows)))
}}
fn create()->Result<Key>{unsafe{let mut sd=std::ptr::null_mut();if ConvertStringSecurityDescriptorToSecurityDescriptorW(wide("O:BAG:BAD:P(A;;KA;;;SY)(A;;KA;;;BA)(A;;KR;;;BU)").as_ptr(),1,&mut sd,std::ptr::null_mut())==0{return Err(bad());}let sa=SECURITY_ATTRIBUTES{nLength:std::mem::size_of::<SECURITY_ATTRIBUTES>()as u32,lpSecurityDescriptor:sd,bInheritHandle:0};let mut h=std::ptr::null_mut();let r=RegCreateKeyExW(HKEY_LOCAL_MACHINE,wide(KEY).as_ptr(),0,std::ptr::null(),REG_OPTION_NON_VOLATILE,KEY_ALL_ACCESS|KEY_WOW64_64KEY,&sa,&mut h,std::ptr::null_mut());LocalFree(sd);if r!=0{return Err(bad());}let h=Key(h);check(h.0)?;Ok(h)}}
fn set(k:HKEY,name:&str,kind:u32,b:&[u8])->Result<()>{if unsafe{RegSetValueExW(k,wide(name).as_ptr(),0,kind,b.as_ptr(),b.len()as u32)}!=0{return Err(bad());}Ok(())}
pub fn restore(snapshot:&Snapshot)->Result<()>{unsafe{
 let mut parent=std::ptr::null_mut();let parent_path=r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall";if RegOpenKeyExW(HKEY_LOCAL_MACHINE,wide(parent_path).as_ptr(),0,KEY_ALL_ACCESS|KEY_WOW64_64KEY,&mut parent)!=0{return Err(bad());}let parent=Key(parent);let r=RegDeleteTreeW(parent.0,wide("Kat Client").as_ptr());if r!=0&&r!=ERROR_FILE_NOT_FOUND{return Err(bad());}
 if let Some(rows)=&snapshot.0{let key=create()?;for(name,kind,b)in rows{set(key.0,name,*kind,b)?;}}Ok(())
}}
pub fn register(root:&Path,runtime:&Path)->Result<()>{let estimated=crate::installer_files::installed_size_kib(root,runtime)?;let key=create()?;let sz=|s:&str|wide(s).iter().flat_map(|c|c.to_le_bytes()).collect::<Vec<_>>();for(name,value)in [("DisplayName","Kat".into()),("DisplayVersion","0.1.0".into()),("Publisher","Kat".into()),("InstallLocation",root.to_string_lossy().into_owned()),("DisplayIcon",format!("\"{}\",0",root.join("kat-desktop.exe").display())),("UninstallString",format!("\"{}\"",root.join("Kat-Uninstall.exe").display()))]{set(key.0,name,REG_SZ,&sz(&value))?;}for(name,value)in [("KatInstallerSchema",1u32),("NoModify",1),("NoRepair",1),("EstimatedSize",estimated)]{set(key.0,name,REG_DWORD,&value.to_le_bytes())?;}Ok(())}
